// Agrupar tópicos por especialidade e calcular métricas
const topics = $input.all().map(i => i.json.result?.data?.json ?? []).flat();
const referenceMonth = $now.minus({months:1}).format('yyyy-MM');

const bySpecialty = {};
for (const t of topics) {
  const key = t.medical_specialty || 'Geral';
  if (!bySpecialty[key]) {
    bySpecialty[key] = {
      medical_specialty: key,
      specialty_category: t.specialty_category || 'Geral',
      topics: [],
      articles: [],
      articlesWithPdf: 0,
      journals: new Set(),
    };
  }
  bySpecialty[key].topics.push(t);
  if (t.articles) {
    for (const a of t.articles) {
      bySpecialty[key].articles.push(a);
      if (a.pdf_available) bySpecialty[key].articlesWithPdf++;
      if (a.journal) bySpecialty[key].journals.add(a.journal);
    }
  }
}

const result = Object.values(bySpecialty).map(s => ({
  medical_specialty: s.medical_specialty,
  specialty_category: s.specialty_category,
  total_topics: s.topics.length,
  total_articles: s.articles.length,
  articles_with_pdf: s.articlesWithPdf,
  avg_articles_per_topic: s.topics.length > 0 ? +(s.articles.length / s.topics.length).toFixed(2) : 0,
  top_journals: [...s.journals].slice(0, 5),
  evidence_strength: s.articles.length >= 5 ? 'forte' : s.articles.length >= 2 ? 'moderada' : 'limitada',
  topics_list: s.topics,
  articles_list: s.articles,
  reference_month: referenceMonth,
}));

return result.map(r => ({ json: r }));

