// Parsear clusters retornados pelo Claude
const raw = $input.first().json.content?.[0]?.text ?? '{"clusters":[]}';
let clusters = [];
try {
  const parsed = JSON.parse(raw.replace(/```json\n?|```/g, '').trim());
  clusters = parsed.clusters ?? [];
} catch(e) {
  clusters = [];
}

const specialty = $('Agregar por especialidade').item.json.medical_specialty;
const articles = $('Agregar por especialidade').item.json.articles_list ?? [];

const enriched = clusters
  .filter(c => c.pmids && c.pmids.length >= 2)
  .map(c => ({
    cluster_topic: c.cluster_topic,
    pmids: c.pmids,
    total_articles: c.pmids.length,
    medical_specialty: specialty,
    articles: articles.filter(a => c.pmids.includes(a.pmid)),
    evidence_level: c.pmids.length >= 5 ? 'A' : c.pmids.length >= 2 ? 'B' : 'C',
  }));

return enriched.map(c => ({ json: c }));

// Determinar consenso a partir do texto da meta-análise
const text = ($input.first().json.content?.[0]?.text ?? '').toLowerCase();
let consensus = 'inconclusivo';
if (text.includes('concordância') || text.includes('consistente') || text.includes('unanime')) {
  consensus = 'concordante';
} else if (text.includes('controvér') || text.includes('conflitante') || text.includes('divergen')) {
  consensus = 'controverso';
}

return [{
  json: {
    meta_analysis_text: $input.first().json.content?.[0]?.text ?? '',
    consensus,
    cluster_topic: $('1 cluster por vez').item.json.cluster_topic,
    pmids: $('1 cluster por vez').item.json.pmids,
    total_articles: $('1 cluster por vez').item.json.total_articles,
    medical_specialty: $('1 cluster por vez').item.json.medical_specialty,
    evidence_level: $('1 cluster por vez').item.json.evidence_level,
  }
}];

